//  StockCatalog.swift — the film and paper library, read from the bundle.
//
//  The catalogue is the Mac app's own `Resources/StockCatalog.json`
//  (generated by `modern_UI/.../Tools/gen-catalog.py` from the engine's
//  profiles), copied in by `Tools/bundle-engine.sh`, so the two apps cannot
//  list different stocks. The rules below are the Mac's `StockCatalog` rules:
//  grouping on `type`, a declared pairing, and black and white printing only
//  on silver paper.
//
//  Black and white is listed here: its profiles (`engine/resources_product/`)
//  ship in this bundle, so there is nothing to gate.

import Foundation

struct Stock: Codable, Identifiable, Hashable, Sendable {
    let id: String
    let name: String
    let stage: String          // "filming" | "printing"
    let use: String            // "still" | "cine"
    let type: String?
    let targetPrint: String?
    let cover: String?
    let monochrome: Bool?

    var isMonochrome: Bool { monochrome ?? false }
    var isFilm: Bool { stage == "filming" }
    var isPaper: Bool { stage == "printing" }
    var isCine: Bool { use == "cine" }
    /// A reversal (slide) film: already a viewable image, scanned, not printed.
    var isPositive: Bool { type == "positive" }
    var coverURL: URL? {
        cover.flatMap { Bundle.main.url(forResource: $0, withExtension: nil, subdirectory: "FilmCovers") }
    }
}

struct StockCatalog: Sendable {
    let stocks: [Stock]

    static let shared: StockCatalog = {
        guard let url = Bundle.main.url(forResource: "StockCatalog", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let decoded = try? JSONDecoder().decode(Wrapper.self, from: data)
        else { return StockCatalog(stocks: []) }
        return StockCatalog(stocks: decoded.stocks)
    }()

    private struct Wrapper: Decodable { let stocks: [Stock] }

    var films: [Stock] { stocks.filter(\.isFilm) }
    var papers: [Stock] { stocks.filter(\.isPaper) }
    func stock(_ id: String) -> Stock? { stocks.first { $0.id == id } }

    enum FilmGroup: CaseIterable, Sendable { case negative, positive, blackAndWhite, cine }

    /// Still before cine, as on the Mac; colour negative, slide, then B&W.
    func films(in group: FilmGroup) -> [Stock] {
        switch group {
        case .negative: films.filter { !$0.isCine && !$0.isPositive && !$0.isMonochrome }
        case .positive: films.filter { !$0.isCine && $0.isPositive }
        case .blackAndWhite: films.filter { !$0.isCine && $0.isMonochrome }
        case .cine: films.filter(\.isCine)
        }
    }

    /// Whether `paper` can print `film` at all: silver on silver, colour on
    /// colour. A B&W negative on colour paper prints orange.
    func canPrint(film: String, on paper: String) -> Bool {
        guard let f = stock(film), let p = stock(paper) else { return true }
        return f.isMonochrome == p.isMonochrome
    }

    func isDeclaredPairing(film: String, paper: String) -> Bool {
        stock(film)?.targetPrint == paper
    }
}
